import{_ as d,c as e,o as a,a2 as l}from"./chunks/framework.D30IVGRC.js";const n=JSON.parse('{"title":"模型列表及对比","description":"","frontmatter":{},"headers":[],"relativePath":"apps-python/ocr-vlm/docs/models.md","filePath":"apps-python/ocr-vlm/docs/models.md","lastUpdated":1746559076000}'),r={name:"apps-python/ocr-vlm/docs/models.md"};function h(o,t,P,i,_,s){return a(),e("div",null,t[0]||(t[0]=[l('<h1 id="模型列表及对比" tabindex="-1">模型列表及对比 <a class="header-anchor" href="#模型列表及对比" aria-label="Permalink to &quot;模型列表及对比&quot;">​</a></h1><p>本文档列出了PaddleXOCR中各个模块支持的模型及其性能对比。这些模型针对不同的应用场景和设备环境进行了优化，用户可以根据实际需求选择合适的模型。</p><h2 id="印章文本检测模块" tabindex="-1">印章文本检测模块 <a class="header-anchor" href="#印章文本检测模块" aria-label="Permalink to &quot;印章文本检测模块&quot;">​</a></h2><p>印章文本检测模块通常会输出文本区域的多点边界框，这些边界框将作为输入传递给弯曲矫正和文本识别模块进行后续处理，识别出印章的文字内容。</p><table tabindex="0"><thead><tr><th>模型</th><th>检测Hmean（%）</th><th>GPU推理耗时（ms）</th><th>CPU推理耗时 (ms)</th><th>模型存储大小（M)</th><th>介绍</th></tr></thead><tbody><tr><td>PP-OCRv4_server_seal_det</td><td>98.21</td><td>84.341</td><td>2425.06</td><td>109</td><td>PP-OCRv4的服务端印章文本检测模型，精度更高，适合在较好的服务器上部署</td></tr><tr><td>PP-OCRv4_mobile_seal_det</td><td>96.47</td><td>10.5878</td><td>131.813</td><td>4.6</td><td>PP-OCRv4的移动端印章文本检测模型，效率更高，适合在端侧部署</td></tr></tbody></table><p><em>注：以上精度指标的评估集是自建的数据集，包含500张圆形印章图像。GPU 推理耗时基于 NVIDIA Tesla T4 机器，精度类型为 FP32， CPU 推理速度基于 Intel(R) Xeon(R) Gold 5117 CPU @ 2.00GHz，线程数为 8，精度类型为 FP32。</em></p><h2 id="表格结构识别模块" tabindex="-1">表格结构识别模块 <a class="header-anchor" href="#表格结构识别模块" aria-label="Permalink to &quot;表格结构识别模块&quot;">​</a></h2><p>表格结构识别是表格识别系统中的重要组成部分，能够将不可编辑表格图片转换为可编辑的表格形式（例如html）。</p><table tabindex="0"><thead><tr><th>模型</th><th>精度（%）</th><th>GPU推理耗时 (ms)</th><th>CPU推理耗时 (ms)</th><th>模型存储大小 (M)</th><th>介绍</th></tr></thead><tbody><tr><td>SLANet</td><td>59.52</td><td>522.536</td><td>1845.37</td><td>6.9</td><td>SLANet 是百度飞桨视觉团队自研的表格结构识别模型。该模型通过采用CPU友好型轻量级骨干网络PP-LCNet、高低层特征融合模块CSP-PAN、结构与位置信息对齐的特征解码模块SLA Head，大幅提升了表格结构识别的精度和推理速度。</td></tr><tr><td>SLANet_plus</td><td>63.69</td><td>522.536</td><td>1845.37</td><td>6.9</td><td>SLANet_plus 是百度飞桨视觉团队自研的表格结构识别模型SLANet的增强版。相较于SLANet，SLANet_plus 对无线表、复杂表格的识别能力得到了大幅提升，并降低了模型对表格定位准确性的敏感度，即使表格定位出现偏移，也能够较准确地进行识别。</td></tr></tbody></table><p><em>注：以上精度指标测量自PaddleX 内部自建英文表格识别数据集。所有模型 GPU 推理耗时基于 NVIDIA Tesla T4 机器，精度类型为 FP32， CPU 推理速度基于 Intel(R) Xeon(R) Gold 5117 CPU @ 2.00GHz，线程数为8，精度类型为 FP32。</em></p><h2 id="文本识别模块" tabindex="-1">文本识别模块 <a class="header-anchor" href="#文本识别模块" aria-label="Permalink to &quot;文本识别模块&quot;">​</a></h2><p>文本识别模块是OCR系统中的核心部分，负责从图像中的文本区域提取出文本信息。</p><table tabindex="0"><thead><tr><th>模型</th><th>识别 Avg Accuracy(%)</th><th>GPU推理耗时（ms）</th><th>CPU推理耗时 (ms)</th><th>模型存储大小（M）</th><th>介绍</th></tr></thead><tbody><tr><td>PP-OCRv4_mobile_rec</td><td>78.20</td><td>7.95018</td><td>46.7868</td><td>10.6</td><td>PP-OCRv4是百度飞桨视觉团队自研的文本识别模型PP-OCRv3的下一个版本，通过引入数据增强方案、GTC-NRTR指导分支等策略，在模型推理速度不变的情况下，进一步提升了文本识别精度。该模型提供了服务端（server）和移动端（mobile）两个不同版本，来满足不同场景下的工业需求。</td></tr><tr><td>PP-OCRv4_server_rec</td><td>79.20</td><td>7.19439</td><td>140.179</td><td>71.2</td><td>同上，服务器端版本。</td></tr></tbody></table><p><em>注：以上精度指标的评估集是 PaddleOCR 自建的中文数据集，覆盖街景、网图、文档、手写多个场景，其中文本识别包含 1.1w 张图片。所有模型 GPU 推理耗时基于 NVIDIA Tesla T4 机器，精度类型为 FP32， CPU 推理速度基于 Intel(R) Xeon(R) Gold 5117 CPU @ 2.00GHz，线程数为8，精度类型为 FP32。</em></p><h2 id="文档图像方向分类模块" tabindex="-1">文档图像方向分类模块 <a class="header-anchor" href="#文档图像方向分类模块" aria-label="Permalink to &quot;文档图像方向分类模块&quot;">​</a></h2><p>文档图像方向分类模块主要是将文档图像的方向区分出来，并使用后处理将其矫正。</p><table tabindex="0"><thead><tr><th>模型</th><th>Top-1 Acc（%）</th><th>GPU推理耗时（ms）</th><th>CPU推理耗时 (ms)</th><th>模型存储大小（M)</th><th>介绍</th></tr></thead><tbody><tr><td>PP-LCNet_x1_0_doc_ori</td><td>99.06</td><td>3.84845</td><td>9.23735</td><td>7</td><td>基于PP-LCNet_x1_0的文档图像分类模型，含有四个类别，即0度，90度，180度，270度</td></tr></tbody></table><p><em>注：以上精度指标的评估集是自建的数据集，覆盖证件和文档等多个场景，包含 1000 张图片。GPU 推理耗时基于 NVIDIA Tesla T4 机器，精度类型为 FP32， CPU 推理速度基于 Intel(R) Xeon(R) Gold 5117 CPU @ 2.00GHz，线程数为 8，精度类型为 FP32。</em></p><h2 id="版面区域检测模块" tabindex="-1">版面区域检测模块 <a class="header-anchor" href="#版面区域检测模块" aria-label="Permalink to &quot;版面区域检测模块&quot;">​</a></h2><p>版面区域检测任务的核心是对输入的文档图像进行内容解析和区域划分。</p><table tabindex="0"><thead><tr><th>模型</th><th>mAP(0.5)（%）</th><th>GPU推理耗时（ms）</th><th>CPU推理耗时 (ms)</th><th>模型存储大小（M）</th><th>介绍</th></tr></thead><tbody><tr><td>PicoDet_layout_1x</td><td>86.8</td><td>13.0</td><td>91.3</td><td>7.4</td><td>基于PicoDet-1x在PubLayNet数据集训练的高效率版面区域定位模型，可定位包含文字、标题、表格、图片以及列表这5类区域</td></tr><tr><td>PicoDet-S_layout_3cls</td><td>87.1</td><td>13.5</td><td>45.8</td><td>4.8</td><td>基于PicoDet-S轻量模型在中英文论文、杂志和研报等场景上自建数据集训练的高效率版面区域定位模型，包含3个类别：表格，图像和印章</td></tr><tr><td>PicoDet-S_layout_17cls</td><td>70.3</td><td>13.6</td><td>46.2</td><td>4.8</td><td>基于PicoDet-S轻量模型在中英文论文、杂志和研报等场景上自建数据集训练的高效率版面区域定位模型，包含17个版面常见类别</td></tr><tr><td>PicoDet-L_layout_3cls</td><td>89.3</td><td>15.7</td><td>159.8</td><td>22.6</td><td>基于PicoDet-L在中英文论文、杂志和研报等场景上自建数据集训练的高效率版面区域定位模型，包含3个类别：表格，图像和印章</td></tr><tr><td>PicoDet-L_layout_17cls</td><td>79.9</td><td>17.2</td><td>160.2</td><td>22.6</td><td>基于PicoDet-L在中英文论文、杂志和研报等场景上自建数据集训练的高效率版面区域定位模型，包含17个版面常见类别</td></tr><tr><td>RT-DETR-H_layout_3cls</td><td>95.9</td><td>114.6</td><td>3832.6</td><td>470.1</td><td>基于RT-DETR-H在中英文论文、杂志和研报等场景上自建数据集训练的高精度版面区域定位模型，包含3个类别：表格，图像和印章</td></tr><tr><td>RT-DETR-H_layout_17cls</td><td>92.6</td><td>115.1</td><td>3827.2</td><td>470.2</td><td>基于RT-DETR-H在中英文论文、杂志和研报等场景上自建数据集训练的高精度版面区域定位模型，包含17个版面常见类别</td></tr></tbody></table><p><em>注：以上精度指标的评估集是 PaddleOCR 自建的版面区域分析数据集，包含中英文论文、杂志和研报等常见的 1w 张文档类型图片。GPU 推理耗时基于 NVIDIA Tesla T4 机器，精度类型为 FP32， CPU 推理速度基于 Intel(R) Xeon(R) Gold 5117 CPU @ 2.00GHz，线程数为 8，精度类型为 FP32。</em></p><h2 id="文本检测模块" tabindex="-1">文本检测模块 <a class="header-anchor" href="#文本检测模块" aria-label="Permalink to &quot;文本检测模块&quot;">​</a></h2><p>文本检测模块是OCR系统中的关键组成部分，负责在图像中定位和标记出包含文本的区域。</p><table tabindex="0"><thead><tr><th>模型</th><th>检测Hmean（%）</th><th>GPU推理耗时（ms）</th><th>CPU推理耗时 (ms)</th><th>模型存储大小（M)</th><th>介绍</th></tr></thead><tbody><tr><td>PP-OCRv4_server_det</td><td>82.69</td><td>83.3501</td><td>2434.01</td><td>109</td><td>PP-OCRv4 的服务端文本检测模型，精度更高，适合在性能较好的服务器上部署</td></tr><tr><td>PP-OCRv4_mobile_det</td><td>77.79</td><td>10.6923</td><td>120.177</td><td>4.7</td><td>PP-OCRv4 的移动端文本检测模型，效率更高，适合在端侧设备部署</td></tr></tbody></table><p><em>注：以上精度指标的评估集是 PaddleOCR 自建的中文数据集，覆盖街景、网图、文档、手写多个场景。GPU 推理耗时基于 NVIDIA Tesla T4 机器，精度类型为 FP32， CPU 推理速度基于 Intel(R) Xeon(R) Gold 5117 CPU @ 2.00GHz，线程数为 8，精度类型为 FP32。</em></p><h2 id="模型适用场景对比" tabindex="-1">模型适用场景对比 <a class="header-anchor" href="#模型适用场景对比" aria-label="Permalink to &quot;模型适用场景对比&quot;">​</a></h2><h3 id="高精度需求场景" tabindex="-1">高精度需求场景 <a class="header-anchor" href="#高精度需求场景" aria-label="Permalink to &quot;高精度需求场景&quot;">​</a></h3><p>在对文档信息抽取精度要求极高的场景，如金融合同审核、法律文件分析等，推荐以下模型组合：</p><ul><li>版面区域检测：RT-DETR-H系列模型</li><li>文本检测：PP-OCRv4_server_det</li><li>文本识别：PP-OCRv4_server_rec</li><li>表格结构识别：SLANet_plus</li><li>印章文本检测：PP-OCRv4_server_seal_det</li><li>文档图像方向分类：PP-LCNet_x1_0_doc_ori</li></ul><p>虽然这些模型推理速度较慢或存储大小较大，但能保证较高的准确性。</p><h3 id="移动端或低资源环境场景" tabindex="-1">移动端或低资源环境场景 <a class="header-anchor" href="#移动端或低资源环境场景" aria-label="Permalink to &quot;移动端或低资源环境场景&quot;">​</a></h3><p>对于移动端应用或资源受限的环境，如手机端文档处理APP、嵌入式设备等，推荐以下模型组合：</p><ul><li>版面区域检测：PicoDet-S_layout_3cls或PicoDet-S_layout_17cls</li><li>文本检测：PP-OCRv4_mobile_det</li><li>文本识别：PP-OCRv4_mobile_rec</li><li>印章文本检测：PP-OCRv4_mobile_seal_det</li></ul><p>这些模型在保证一定精度的前提下，能够满足移动端设备的性能和存储要求。</p><h3 id="平衡性能场景" tabindex="-1">平衡性能场景 <a class="header-anchor" href="#平衡性能场景" aria-label="Permalink to &quot;平衡性能场景&quot;">​</a></h3><p>在对精度和速度都有一定要求的场景，如企业内部日常文档处理、小型办公系统等，推荐以下模型组合：</p><ul><li>版面区域检测：PicoDet-L_layout_3cls或PicoDet-L_layout_17cls</li><li>文本检测：根据设备性能选择PP-OCRv4_mobile_det或PP-OCRv4_server_det</li><li>文本识别：根据精度需求选择PP-OCRv4_mobile_rec或PP-OCRv4_server_rec</li><li>表格结构识别：SLANet</li><li>印章文本检测：根据设备性能选择PP-OCRv4_mobile_seal_det或PP-OCRv4_server_seal_det</li><li>文档图像方向分类：PP-LCNet_x1_0_doc_ori</li></ul><p>这种组合在精度和速度之间找到合适的平衡点。</p>',39)]))}const m=d(r,[["render",h]]);export{n as __pageData,m as default};
